            key = ((sequence, event.get("revision", 0), position) if sequence_first
                   else (event.get("revision", 0), position))
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), mode)
            base = raw if tax_original else net
            tax = rounded(base * event.get("tax_bp", 0), mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _dependency_resolver():
    from itertools import product

    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        rows_by_version = {
            name: {row["version"]: row for row in rows}
            for name, rows in packages.items()
        }
        domains = [[-1] + sorted(rows_by_version[name]) for name in names]
        best_vector = None
        best = None

        for values in product(*domains):
            chosen = dict(zip(names, values))
            installed = set()
            finished = set()
            active = set()

            def visit(name, low, high):
                version = chosen.get(name, -1)
                if version < low or version > high or version == -1:
                    return False
                if version in blocked.get(name, ()):
                    return False
                if name in pins and version != pins[name]:
                    return False
                if name in active:
                    return False
                installed.add(name)
                if name in finished:
                    return True
                row = rows_by_version[name].get(version)
                if row is None:
                    return False
                active.add(name)
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    if not visit(dep["name"], dep["min"], dep["max"]):
                        return False
                active.remove(name)
                finished.add(name)
                return True

            valid = True
            for name, bounds in data["roots"].items():
                if not visit(name, bounds[0], bounds[1]):
                    valid = False
                    break
            if not valid or any((chosen[name] != -1) != (name in installed)
                                for name in names):
                continue
            vector = tuple(chosen[name] for name in names)
            if best_vector is None or vector < best_vector:
                best_vector = vector
                best = {name: chosen[name] for name in names if chosen[name] != -1}

        return {"versions": best} if best is not None else {"error": "unsatisfiable"}
    return solve


def _quota_intervals():
    from itertools import combinations

    def feasible(selection, data):
        ids = {job["id"] for job in selection}
        if not set(data.get("mandatory", [])).issubset(ids):
            return False
        counts = {}
        for job in selection:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        for group, bounds in data.get("quotas", {}).items():
            if not bounds[0] <= counts.get(group, 0) <= bounds[1]:
                return False
        ordered = sorted(selection, key=lambda j: (j["start"], j["end"]))
        for previous, current in zip(ordered, ordered[1:]):
            if previous["end"] > current["start"]:
                return False
        return True

    def solve(data):
        options = [job for job in data["jobs"]
                   if job["id"] not in data.get("blocked", [])]
        best_value = None
        best_ids = None
        for selection in combinations(options, data["k"]):
            if not feasible(selection, data):
                continue
            value = sum(job["value"] for job in selection)
            ids = sorted(job["id"] for job in selection)
            if (best_value is None or value > best_value or
                    (value == best_value and ids > best_ids)):
                best_value, best_ids = value, ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _temporal_routes():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = bit_for.get(data["source"], 0)
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_state = (data["source"], initial_mask, data["coupons"])
        distances = {start_state: data["start"]}
        queue = [(data["start"], data["source"], initial_mask,
                  data["coupons"])]
        while queue:
            arrival, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != arrival:
                continue
            if (node == data["target"] and mask == full and remaining == 0):
                return {"arrival": arrival}
            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                moves = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(1, edge["duration"] - edge.get("discount", 0))
                    moves.append((duration, remaining - 1))
                for duration, next_remaining in moves:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bit_for.get(next_node, 0)
                    next_state = (next_node, next_mask, next_remaining)
                    if next_time < distances.get(next_state, float("inf")):
                        distances[next_state] = next_time
                        heapq.heappush(queue, (next_time, next_node, next_mask,
                                               next_remaining))
        return {"arrival": None}
    return solve


